<div x-data="{kitId:@js((string)($current['kit_id']??($kits->count()===1?$kits->first()->id:''))),mode:@js($current['mode']??'follow'),overrides:@js(array_keys($current['overrides']??[])),review:null,busy:false,error:'',async preview(url){this.busy=true;this.review=null;this.error='';try{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({kit_id:this.kitId,mode:this.mode,overrides:this.overrides,preview:true})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Cannot preview assignment');this.review=data.changes;}catch(e){this.error=e.message}finally{this.busy=false}}}">
